class Player extends Schema {
  @type('string') sessionId
  @type('string') name
  @type('string') role
  @type('boolean') isHuman
  @type('number') actionPoints = 3
  @type('boolean') hasSubmitted = false
  @type('boolean') connected = true
}

class GameState extends Schema {
  @type('string') phase: 'lobby' | 'action' | 'consequence' | 'end'
  @type('number') round = 0
  @type('number') publicScore = 75
  @type('string') roomCode
  @type({ map: Player }) players
}

// shared/messages.ts
const SubmitActionSchema = z.object({
  actionId: z.string(),
  actionPointsSpent: z.number().min(1).max(3),
  reasoning: z.string().optional()
})

// GameRoom.ts
onMessage('submit_action', (client, message) => {
  const validated = SubmitActionSchema.parse(message)
  // Process action...
})

const submitActionTool = {
  type: 'function',
  function: {
    name: 'submit_action',
    description: 'Submit your selected action for this round',
    parameters: {
      type: 'object',
      properties: {
        actionId: { type: 'string', description: 'ID of action' },
        reasoning: { type: 'string', description: 'Your reasoning' }
      },
      required: ['actionId']
    }
  }
}
